s*<strong>SKU:\\s*</strong>\\s*([A-Za-z0-9-]+)\\s*</p>\', 1, 1, \'e\', 1 ) IS NOT NULL THEN TRIM(UPPER( REGEXP_SUBSTR( description, \'<p>\\s*<strong>SKU:\\s*</strong>\\s*([A-Za-z0-9-]+)\\s*</p>\', 1, 1, \'e\', 1 ) )) WHEN REGEXP_SUBSTR( description, \'SKU:\\s*([A-Za-z0-9-]+)\', 1, 1, \'e\', 1 ) IS NOT NULL THEN TRIM(UPPER( REGEXP_SUBSTR( description, \'SKU:\\s*([A-Za-z0-9-]+)\', 1, 1, \'e\', 1 ) )) ELSE NULL END AS sku_group, GREATEST(selling_price, IFNULL(NULLIF(mrp, \'\'), 0))::int AS db_original_price, CASE WHEN IFNULL(NULLIF(mrp, \'\'), 0) != 0 THEN LEAST(IFNULL(NULLIF(mrp, \'\'), 0), selling_price)::int ELSE GREATEST(selling_price, IFNULL(NULLIF(mrp, \'\'), 0))::int END AS db_slashed_price, fit, tags as product_tags, REPLACE(REPLACE(REPLACE(color, \'[\', \'\'), \']\', \'\'), \'\'\'\', \'\') AS color, style, title, collar, REPLACE(REPLACE(REPLACE(colors, \'[\', \'\'), \']\', \'\'), \'\'\'\', \'\') AS colors, status, pattern, sleeves, material, washcare, occassion, ifnull(nullif(sort_rank,\'\'),0)::int as sort_rank, long_title, nullif(created_at,\'\')::date AS created_at, nullif(updated_at,\'\')::date AS updated_at, nullif(published_at,\'\')::date AS published_at, color_group, SPLIT_PART(REPLACE(REPLACE(images, \'[\', \'\'), \']\', \'\'), \',\', 1) AS first_image, preview_image, REPLACE(REPLACE(similar_products, \']\', \'\'), \'[\', \'\') AS similar_products, global_sort_score, short_description, color_variants_ids, shopify_product_id AS id, shopify_product_type AS category, description FROM snitch_db.maplemonk.s3_bucket_products_db );",
